import * as z from 'zod';
/** Schema for a funder item */
export const FunderSchema = z
    .object({
    id: z.string().brand(),
    name: z.string(),
    link: z.string().url(),
    image: z.string(),
})
    .meta({ id: 'Funder' });
/** Schema for multiple funders */
export const FundersSchema = z
    .object({
    $schema: z.string(),
    funders: FunderSchema.array(),
})
    .meta({ id: 'Funders' });
export default FundersSchema;
